import React, { useEffect, useState } from "react";
import io from "socket.io-client";

const backEndUrl = "http://localhost:8000";

const Chat = () => {
    const [user, setUser] = useState("");
    const [room, setRoom] = useState("");
    const [socket, setSocket] = useState(null);

    useEffect(() => {
        const searchParams = new URLSearchParams(window.location.search);
        const name = searchParams.get("name") || "Anonymous"; 
        const roomParam = searchParams.get("room") || "General"; 

        console.log("User:", name, "Room:", roomParam);
        setUser(name);
        setRoom(roomParam);

        const newSocket = io(backEndUrl, { transports: ["websocket"] });
        setSocket(newSocket);

        newSocket.on("connect", () => {
            console.log("Connected to server");
            newSocket.emit("joinRoom", { name, room: roomParam });
        });

        return () => {
            newSocket.disconnect(); 
        };
    }, []);

    return (
        <div style={{ textAlign: "center", padding: "20px", color: "#fff", background: "#214a80", height: "100vh" }}>
            <h2>Welcome, {user}!</h2>
            <p>You have joined the room: <strong>{room}</strong></p>
            <p>Chat functionality will be implemented here...</p>
        </div>
    );
};

export default Chat;
